def count_great_partitions(nums,k):
    modulus=10**9+7
    if sum(nums)<2*k:return 0
    small=[0]*k;small[0]=1
    for value in nums:
        for total in range(k-1,value-1,-1):
            small[total]=(small[total]+small[total-value])%modulus
    return (pow(2,len(nums),modulus)-2*sum(small))%modulus

